	public ThirdPartyAssessment getThirdPartyAssessment( ThirdPartyAssessmentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ThirdPartyAssessmentFetchOneSummary arg cannot be null" );

		ThirdPartyAssessment entity = null;
		UUID id = summary.getThirdPartyAssessmentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ThirdPartyAssessment using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


